    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof generateSignalsNow>>, TError,void, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof generateSignalsNow>>, TError,void, TContext> => {

const mutationKey = getGenerateSignalsNowMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof generateSignalsNow>>, void> = () => {


          return  generateSignalsNow(requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type GenerateSignalsNowMutationResult = NonNullable<Awaited<ReturnType<typeof generateSignalsNow>>>

    export type GenerateSignalsNowMutationError = ErrorType<unknown>


    /**
 * @summary Manually trigger one signal generation cycle
 */
export const useGenerateSignalsNow = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof generateSignalsNow>>, TError,void, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof generateSignalsNow>>,
        TError,
        void,
        TContext
      > => {
      return useMutation(getGenerateSignalsNowMutationOptions(options));
    }

